import React, { useState, useEffect } from 'react';
import { AuthProvider } from './context/AuthContext';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Home from './pages/Home';
import Catalog from './pages/Catalog';
import ProductPage from './pages/ProductPage';
import Profile from './pages/Profile';
import Auth from './pages/Auth';

function App() {
  const [currentPage, setCurrentPage] = useState('home');
  const [pageParams, setPageParams] = useState({});

  // Обработка хэша в URL
  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash.replace('#', '');
      console.log('Hash changed to:', hash);

      if (hash) {
        const [page, param] = hash.split('/');
        setCurrentPage(page);
        setPageParams({ id: param });
      } else {
        setCurrentPage('home');
      }
    };

    window.addEventListener('hashchange', handleHashChange);
    handleHashChange();

    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  // Функция навигации
  const navigate = (page, params = {}) => {
    console.log('Navigating to:', page, params);
    setCurrentPage(page);
    setPageParams(params);
    window.location.hash = page + (params.id ? `/${params.id}` : '');
  };

  // Рендер текущей страницы
  const renderPage = () => {
    console.log('Rendering page:', currentPage);

    switch (currentPage) {
      case 'catalog':
        return <Catalog onNavigate={navigate} />;
      case 'product':
        return <ProductPage onNavigate={navigate} />;
      case 'profile':
        return <Profile onNavigate={navigate} />;
      case 'auth':
        return <Auth onNavigate={navigate} />; // ✅ Убедитесь, что передается onNavigate
      default:
        return <Home onNavigate={navigate} />;
    }
  };

  return (
    <AuthProvider>
      <div className="min-h-screen bg-white">
        <Navbar onNavigate={navigate} />
        {renderPage()}
        <Footer />
      </div>
    </AuthProvider>
  );
}

export default App;
